BEGIN;
DELETE FROM relatorio_vendas WHERE data_ref = :data;
INSERT INTO relatorio_vendas
SELECT :data AS data_ref, canal, SUM(valor_pago) AS receita
FROM fato_pedidos WHERE data_pedido = :data AND status = 'entregue'
GROUP BY canal;
COMMIT;

